pragma solidcash ^0.50.0;

/* Standing Order (token): a recurring payment in a fungible CashToken, e.g. a BCH stablecoin.
 *
 * The contract UTXO holds the subscription balance as fungible tokens of `category` plus a small amount
 * of BCH that pays the claim fees. After each `period` blocks anyone may trigger `claim`, which pays the
 * merchant exactly `tokensPerPeriod` tokens (with `dust` satoshis to carry them) and returns the rest
 * of the tokens to this same contract. The subscriber can `cancel` at any time.
 */
contract StandingOrderToken(
    bytes20 merchant,
    bytes20 subscriber,
    bytes32 category,
    int tokensPerPeriod,
    int period,
    int dust,
    int maxFee,
    // Random per subscription: gives every order its own covenant address, so subscribing to the same plan
    // twice never makes one covenant pay twice per period. Not used by the logic.
    bytes8 orderId
) {
    function claim() {
        require(this.age >= period);

        // Exactly one input: a claim may only ever spend this one order UTXO.
        require(tx.inputs.length == 1);

        // Only the order's own token category is ever moved by a claim.
        require(tx.inputs[this.activeInputIndex].tokenCategory == category);

        // Output 0 pays the merchant in tokens of this category.
        require(tx.outputs[0].lockingBytecode == new LockingBytecodeP2PKH(merchant));
        require(tx.outputs[0].tokenCategory == category);

        int tokensLeft = tx.inputs[this.activeInputIndex].tokenAmount;
        int satsLeft = tx.inputs[this.activeInputIndex].value;

        if (tokensLeft <= tokensPerPeriod) {
            // Last claim: all remaining tokens go to the merchant; the order ends.
            require(tx.outputs.length == 1);
            require(tx.outputs[0].tokenAmount == tokensLeft);
            // ...together with the contract's BCH (minus at most maxFee), so no one else can take it.
            require(tx.outputs[0].value >= satsLeft - maxFee);
        } else {
            // Regular claim: exactly one period's tokens; the rest stays in this contract. Exactly two outputs.
            require(tx.outputs.length == 2);
            require(tx.outputs[0].tokenAmount == tokensPerPeriod);
            require(tx.outputs[0].value <= dust);
            require(tx.outputs[1].lockingBytecode == tx.inputs[this.activeInputIndex].lockingBytecode);
            require(tx.outputs[1].tokenCategory == category);
            require(tx.outputs[1].tokenAmount == tokensLeft - tokensPerPeriod);
            // The contract keeps its BCH, minus the merchant's dust and at most maxFee.
            require(tx.outputs[1].value >= satsLeft - dust - maxFee);
        }
    }

    // Only the subscriber can cancel: the LAST input must be a coin from the subscriber's own address. Their wallet
    // signs that coin as usual (covering every output), so any BCH wallet can cancel; no signature inside the contract.
    function cancel() {
        require(tx.inputs[tx.inputs.length - 1].lockingBytecode == new LockingBytecodeP2PKH(subscriber));
    }
}
